const transferBase = "/api/workspaces/equipe"
const transferAttempt = "73bfeaca-d0ed-4ff5-82fd-9da45e674fd2"

// This reference ID was generated by the Node service's JSON.stringify/SHA-256 algorithm.
func TestWorkspaceImportIDMatchesNode(t *testing.T) {
	if got := importRootID("w", "alice", "test", "Café.md", "<>&\u2028\\u2028\u2029"); got != "27585e63-d54d-87df-8d62-bfc4ee4e3874" {
		t.Fatal(got)
	}
}

func TestWorkspaceFileImport(t *testing.T) {
	w := newReadsWorld(t)
	for _, tc := range []struct{ format, name, source, title, fragment string }{
		{"markdown", "Journal.md", "# Journal du soir\n\n**Bonjour**", "Journal du soir", "Bonjour"},
		{"csv", "Budget.csv", "Article,Montant\n\"Café, filtre\",14", "Budget", "database-row"},
	} {
		in := map[string]any{"name": tc.name, "source": tc.source, "attempt": transferAttempt}
		out := w.post(t, tokenAlice, transferBase+"/import/"+tc.format, in, 200)
		id := out["id"].(string)
		if w.post(t, tokenAlice, transferBase+"/import/"+tc.format, in, 200)["id"] != id {
			t.Fatal("duplicate retry")
		}
		_, doc := w.get(t, tokenAlice, transferBase+"/export/pages/"+id+"?private=1")
		if doc["title"] != tc.title {
			t.Fatalf("wrong title %v", doc)
		}
		raw, _ := json.Marshal(doc["blocks"])
		if !strings.Contains(string(raw), tc.fragment) {
			t.Fatalf("wrong content %s", raw)
		}
		for _, query := range []string{"", "?private=1"} {
			if status, _ := w.get(t, tokenZoe, transferBase+"/export/pages/"+id+query); status != 404 {
				t.Fatalf("another user's private page: %d", status)
			}
		}
	}
	if _, err := w.service.DB.Exec(w.ctx, "UPDATE memberships SET role='viewer' WHERE user_id='alice'"); err != nil {
		t.Fatal(err)
	}
	w.post(t, tokenAlice, transferBase+"/import/csv", map[string]any{"attempt": transferAttempt, "name": "Demo.csv", "source": "x"}, 403)
}

func TestWorkspaceExportPrivacy(t *testing.T) {
	w := newReadsWorld(t)
	w.page(t, "override", "public", visPrivate)
	w.page(t, "nested", "override", visInherit)
	_, err := w.service.DB.Exec(w.ctx, "INSERT INTO page_shares(page_id,user_id,level,granted_by) VALUES('override','alice','edit','alice')")
	if err != nil {
		t.Fatal(err)
	}
	_, idx := w.get(t, tokenAlice, transferBase+"/export/index")
	access := idx["access"].(map[string]any)
	for _, id := range []string{"override", "nested"} {
		if access[id].(map[string]any)["visibility"] != "private" {
			t.Fatal(access)
		}
		route := transferBase + "/export/pages/" + id
		if status, _ := w.get(t, tokenAlice, route); status != 404 {
			t.Fatal(status)
		}
		if status, _ := w.get(t, tokenAlice, route+"?private=1"); status != 200 {
			t.Fatal(status)
		}
	}
	if status, _ := w.get(t, tokenAlice, transferBase+"/export/pages/public"); status != 200 {
		t.Fatal(status)
	}
	_, err = w.service.DB.Exec(w.ctx, "UPDATE pages SET trashed=true WHERE id='nested'")
	if err != nil {
		t.Fatal(err)
	}
	if status, _ := w.get(t, tokenAlice, transferBase+"/export/pages/nested?private=1"); status != 404 {
		t.Fatal(status)
	}
}

func TestWorkspaceNotionZIP(t *testing.T) {
	w := newReadsWorld(t)
	raw, err := os.ReadFile("../../test/fixtures/workspace-import/notion-md-csv.zip")
	if err != nil {
		t.Fatal(err)
	}
	send := func(data []byte) (int, map[string]any) {
		req, err := http.NewRequest(http.MethodPost, w.server.URL+transferBase+"/import/zip?name=Migration.zip&attempt="+transferAttempt, bytes.NewReader(data))
		if err != nil {
			t.Fatal(err)
		}
		req.Header.Set("Authorization", "Bearer "+tokenAlice)
		req.Header.Set("Content-Type", "application/zip")
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			t.Fatal(err)
		}
		defer resp.Body.Close()
		body, _ := io.ReadAll(resp.Body)
		var obj map[string]any
		if err = json.Unmarshal(body, &obj); err != nil {
			t.Fatalf("%d: %s", resp.StatusCode, body)
		}
		return resp.StatusCode, obj
	}
	if status, _ := send([]byte("not a zip")); status != 422 {
		t.Fatal(status)
	}
	status, res := send(raw)
	if status != 200 {
		t.Fatalf("%d %v", status, res)
	}
	if status, retry := send(raw); status != 200 || retry["id"] != res["id"] {
		t.Fatal(status, retry)
	}
	var revision int
	if err = w.service.DB.QueryRow(w.ctx, "SELECT revision FROM workspaces WHERE id='w'").Scan(&revision); err != nil || revision != 1 {
		t.Fatalf("revision %d %v", revision, err)
	}
	_, index := w.get(t, tokenAlice, transferBase+"/export/index")
	ids := map[string]string{}
	parents := map[string]any{}
	for _, item := range index["pages"].([]any) {
		p := item.(map[string]any)
		ids[p["title"].(string)] = p["id"].(string)
		parents[p["title"].(string)] = p["parentId"]
	}
	if ids["Migration"] != res["id"] || parents["Equipe"] != ids["Migration"] || parents["Budget"] != ids["Equipe"] || parents["Café"] != ids["Budget"] {
		t.Fatalf("bad tree %v", parents)
	}
	_, team := w.get(t, tokenAlice, transferBase+"/export/pages/"+ids["Equipe"]+"?private=1")
	markup, _ := json.Marshal(team)
	if !bytes.Contains(markup, []byte("data:image/png;base64,iVBORw0KGgo")) || !strings.Contains(team["blocks"].([]any)[0].(map[string]any)["data"].(map[string]any)["text"].(string), `data-blok-page-id="`+ids["Budget"]+`"`) {
		t.Fatalf("broken image or link %s", markup)
	}
	_, budget := w.get(t, tokenAlice, transferBase+"/export/pages/"+ids["Budget"]+"?private=1")
	row := budget["blocks"].([]any)[1].(map[string]any)["data"].(map[string]any)
	if row["pageId"] != ids["Café"] {
		t.Fatal(row)
	}
}
